{
  "verses": [
    {
      "chapter": 1,
      "text_ar": "فإن زوجتي الأولى ماتت مع أولادي العشرة الآخرين بموت مر.",
      "verse": 6
    },
    {
      "chapter": 1,
      "text_ar": "اسمعوا الآن يا أولادي، وسأكشف لكم ما حدث لي.",
      "verse": 7
    },
    {
      "chapter": 1,
      "text_ar": "كنت رجلاً غنياً جداً أعيش في المشرق في أرض أوسيتيس (عوص)، وقبل أن يسميني الرب أيوب، كنت أُدعى يوباب.",
      "verse": 8
    },
    {
      "chapter": 1,
      "text_ar": "وكانت بداية محنتي هكذا.",
      "verse": 9
    },
    {
      "chapter": 1,
      "text_ar": "بالقرب من بيتي كان يوجد صنم لشخص يعبده الشعب؛ ورأيت باستمرار محرقة تُقدم له كإله.",
      "verse": 10
    }
  ],
  "book_code": "TJOB"
}
